CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name) <= 100), avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.profiles TO authenticated;
GRANT UPDATE (display_name, avatar_path) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY "Create own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY "Edit own profile" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, CHECK (sender_id <> recipient_id));
GRANT SELECT, INSERT ON public.user_messages TO authenticated;
GRANT UPDATE (read_at) ON public.user_messages TO authenticated;
GRANT ALL ON public.user_messages TO service_role;
ALTER TABLE public.user_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Participants read messages" ON public.user_messages FOR SELECT TO authenticated USING (auth.uid() IN (sender_id, recipient_id));
CREATE POLICY "Send own messages" ON public.user_messages FOR INSERT TO authenticated WITH CHECK (sender_id = auth.uid() AND read_at IS NULL);
CREATE POLICY "Recipients mark read" ON public.user_messages FOR UPDATE TO authenticated USING (recipient_id = auth.uid()) WITH CHECK (recipient_id = auth.uid());
CREATE INDEX user_messages_recipient ON public.user_messages(recipient_id, created_at DESC);
CREATE TABLE public.user_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, message_id uuid REFERENCES public.user_messages(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz);
GRANT SELECT ON public.user_notifications TO authenticated;
GRANT UPDATE (read_at) ON public.user_notifications TO authenticated;
GRANT ALL ON public.user_notifications TO service_role;
ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own notifications" ON public.user_notifications FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Mark own notifications read" ON public.user_notifications FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE INDEX user_notifications_owner ON public.user_notifications(user_id, created_at DESC);
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'name', ''), 100)); INSERT INTO public.user_notifications(user_id,title,body) VALUES (NEW.id, 'Welcome to NutriSync', 'Your account is ready.'); RETURN NEW; END; $$;
CREATE TRIGGER create_account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE FUNCTION public.notify_message_recipient() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.user_notifications(user_id,title,body,message_id) SELECT NEW.recipient_id, 'New message', coalesce(nullif(display_name,''),'A team member') || ' sent you a message.', NEW.id FROM public.profiles WHERE id = NEW.sender_id; RETURN NEW; END; $$;
CREATE TRIGGER notify_message_recipient AFTER INSERT ON public.user_messages FOR EACH ROW EXECUTE FUNCTION public.notify_message_recipient();
CREATE FUNCTION public.account_directory() RETURNS TABLE(id uuid, display_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT p.id, coalesce(nullif(p.display_name,''),'Team member') FROM public.profiles p WHERE auth.uid() IS NOT NULL ORDER BY p.display_name; $$;
REVOKE ALL ON FUNCTION public.account_directory() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.account_directory() TO authenticated;
REVOKE ALL ON FUNCTION public.create_account_profile(), public.notify_message_recipient() FROM PUBLIC, anon, authenticated;
CREATE POLICY "Read team avatars" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'user-avatars');
CREATE POLICY "Upload own avatar" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'user-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Replace own avatar" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'user-avatars' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'user-avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
ALTER PUBLICATION supabase_realtime ADD TABLE public.user_messages, public.user_notifications;